fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    // Precondition: end < v.len()
    let mut max_val = v[0];
    let mut max_idx = 0;
    // Scan from 1 up to and including `end`
    for i in 1..=end {
        if v[i] > max_val {
            max_val = v[i];
            max_idx = i;
        }
    }
    (max_val, max_idx)
}

fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    // Precondition: start < v.len()
    let mut min_val = v[start];
    let mut min_idx = start;
    // Scan from `start+1` to the end
    for i in (start + 1)..v.len() {
        if v[i] < min_val {
            min_val = v[i];
            min_idx = i;
        }
    }
    (min_val, min_idx)
}

fn barrier(v: &[i32], p: usize) -> bool {
    // Precondition: !v.is_empty() and p < v.len()
    // If p is the last index, suffix is empty → vacuously true
    if p + 1 >= v.len() {
        return true;
    }
    let (max_pref, _) = find_max_in_prefix(v, p);
    let (min_suff, _) = find_min_in_suffix(v, p + 1);
    max_pref < min_suff
}

